<?php require 'autorizare.php';if(isset($_POST['sterge'])){$id=(int)$_POST['sterge'];$s=$pdo->prepare('DELETE FROM carti WHERE id_carte=?');$s->execute([$id]);}if(isset($_POST['salveaza'])){$id=(int)$_POST['salveaza'];$s=$pdo->prepare('UPDATE carti SET titlu=?,descriere=?,pret=? WHERE id_carte=?');$s->execute([trim($_POST['titlu'][$id]??''),trim($_POST['descriere'][$id]??''),(float)($_POST['pret'][$id]??0),$id]);}$rows=$pdo->query('SELECT c.id_carte,c.titlu,c.descriere,c.pret,a.nume_autor,d.nume_domeniu FROM carti c JOIN autori a ON a.id_autor=c.id_autor JOIN domenii d ON d.id_domeniu=c.id_domeniu ORDER BY c.titlu')->fetchAll();include 'admin_top.php';?><form method="post"><table border="1" cellpadding="4"><tr><th>Carte</th><th>Autor / domeniu</th><th>Descriere</th><th>Pret</th><th>Actiuni</th></tr><?php foreach($rows as $r):$id=(int)$r['id_carte'];?><tr><td><input name="titlu[<?=$id?>]" value="<?=h($r['titlu'])?>"></td><td><?=h($r['nume_autor'])?><br><?=h($r['nume_domeniu'])?></td><td><textarea name="descriere[<?=$id?>]" rows="3"><?=h($r['descriere'])?></textarea></td><td><input type="number" step="0.01" name="pret[<?=$id?>]" value="<?=h($r['pret'])?>" size="7"></td><td><button name="salveaza" value="<?=$id?>">Salveaza</button> <button name="sterge" value="<?=$id?>" onclick="return confirm('Stergi cartea?')">Sterge</button></td></tr><?php endforeach;?></table></form></body></html>
